SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"DJ Gabriel B, also known as Gabriel Beats, is a Santo Domingo DJ and producer who began his career in 2019 and works mainly in tech house and afro house, often building tracks from samples and vocals taken from the local urban scene.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tech house from Santo Domingo","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The music site Discolai describes him as one of the standard-bearers of the new tech house and afro house school in the Dominican capital. He releases tracks such as «Esta Si» and «Flow De Nasa» under the name Gabriel Beats on SoundCloud and Spotify, while Boiler Room lists his set under the genre dembow.","type":"text"}]},{"type":"paragraph","content":[{"text":"Boiler Room Dominican Republic","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"On 3 May 2024 he played at the first Boiler Room event held in the Dominican Republic, staged at the Cinco Esquinas in Santo Domingo’s San Carlos neighborhood and tied to the close of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3e1718be-c12d-42f5-85e7-2156d9574940","displayText":"Tokischa","occurrenceId":"763b6f7f-467e-4c3a-8294-958880d50a30"}},{"text":"’s tour. Alongside him on the bill were the DJ Selektor Siete, who opened, the DJ Mohikaa, the producer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"350e5535-5229-4d49-903e-a5de047e7723","displayText":"Cromo X","occurrenceId":"4979d937-bd8b-40b4-b2e1-a491ffcdbf09"}},{"text":" and the producer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5cbc8f2b-cb68-4ebd-8006-6837be54bbe4","displayText":"Leo RD","occurrenceId":"1854d711-7d29-4c73-bdf2-c5f713c6a298"}},{"text":". Boiler Room published his set on YouTube on 13 June 2024 as «DJ Gabriel B | Boiler Room Dominican Republic: Tokischa», a fifteen-minute recording that has passed 22,000 views.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"As of 2026 he continues to perform and post as a DJ and producer of tech house and house, with a following of about 2,800 on SoundCloud and 18,000 on Instagram, where he uses the handle @gabriel_beats_music. The Boiler Room set is the best documented appearance of his career so far.","type":"text"}]}]}'::jsonb, 'published', id, 2 FROM artists WHERE slug = 'dj-gabriel-b';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
