e":"bold"}]}]},{"type":"paragraph","content":[{"text":"By late 2024 El Blachy was booking around forty parties in November and sixty in December, and had announced collaborations with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cf438c62-e0b8-4ba9-8e4b-f328ddce0c9b","displayText":"Chimbala","occurrenceId":"dde104ae-bb94-4701-a7e2-8e736e393344"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"550df3b5-6488-4aec-a476-a5d28d52ceea","displayText":"Bulin 47","occurrenceId":"e8b6025a-2f28-4022-882f-28ea7636fb0e"}},{"text":". In August 2026 he filled the Coca-Cola Music Hall in Puerto Rico, part of a run of international dates that includes a tour of the United States.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'el-blachy';
