SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Chris Hierro —born in the United States in 1984 and raised between New York and the Dominican Republic— is a Dominican songwriter, producer, arranger and keyboardist, the son of the merengue arranger ","type":"text"},{"type":"artistReference","attrs":{"artistId":"db00c1d0-00ce-4bde-9e7e-f5f6a3bd9250","displayText":"Henry Hierro","occurrenceId":"41bff6a5-f829-41cc-8a40-56e1aad896bd"}},{"text":" and, for more than a decade, keyboardist and director of the band that accompanies the Spanish singer Alejandro Sanz.","type":"text"}]},{"type":"paragraph","content":[{"text":"A musical family","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His father, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"db00c1d0-00ce-4bde-9e7e-f5f6a3bd9250","displayText":"Henry Hierro","occurrenceId":"798eb3c3-a9f2-431a-9a61-f7031e937b4e"}},{"text":", was a founder of the New York merengue orchestra ","type":"text"},{"type":"artistReference","attrs":{"artistId":"908c3016-2aab-424e-9913-664e5f9a04ac","displayText":"Víctor Roque y La Gran Manzana","occurrenceId":"002bce9b-1649-4aea-9030-4504f775b30e"}},{"text":", and his mother, Lucía Guzmán, was a singer, according to Beller Digital. In 2002 he worked on his father’s album «Volví con mi pianito». Living in New York, he formed the group «Nosotros 3» and worked as a vocalist, pianist and producer, singing backup and playing keyboards for Jerry Rivera, Obie Bermúdez and Alejandro Sanz; a BMI panel biography adds that he toured Europe, the United States and Mexico as a backing singer for those artists and for Thalía. In 2010 he founded the rock band «Taxi Amarillo».","type":"text"}]},{"type":"paragraph","content":[{"text":"Writing, arranging and producing","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"BMI listed his early writing, arranging and production credits in 2015 as ","type":"text"},{"type":"artistReference","attrs":{"artistId":"73032c71-e46c-45b1-b02c-8f4de18426ad","displayText":"Los Toros Band","occurrenceId":"91dd65bd-1dbf-441d-a334-593b3842cd56"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"6439cd28-1860-4ada-a40e-91ed23bcbe25"}},{"text":", Andy Andy and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"7b9ee34b-4438-4032-b827-0b748086e223","displayText":"Wason Brazobán","occurrenceId":"3a53a0ba-b1c4-4968-b7db-e1977b5a4f63"}},{"text":". He is credited as one of the musicians on Carlos Vives’s «Cumbiana» (2020), the album that won the Latin Grammy for Best Contemporary Tropical Album, and in May 2021 he co-wrote and produced ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f5937785-a6cb-432a-b1ea-6f6164a77e81","displayText":"Judy Santos","occurrenceId":"92f4fb84-2405-4915-ae0b-074c9cf1284d"}},{"text":"’s «No Me Rendiré», which reached number 24 on Billboard’s Tropical Airplay chart. In 2022 albums he produced for ","type":"text"},{"type":"artistReference","attrs":{"artistId":"070e7449-814e-4ea6-a009-7a091b7e4878","displayText":"Milly Quezada","occurrenceId":"e11f39f6-607b-4a23-8430-191ad6b1c89a"}},{"text":" («Resistirá», six songs arranged and produced by him, her sixth Latin Grammy nomination), ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta “El Torito”","occurrenceId":"5223e232-acc8-4bee-a2e8-71404d843a20"}},{"text":" («Este soy yo») and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"34b63c95-f79a-4f7b-aa1d-426926d12959","displayText":"Pavel Núñez","occurrenceId":"fea28dcd-3b12-41bc-8b38-1cf96f870be7"}},{"text":" («Trópico») were nominated for the Latin Grammy, and he also worked as programmer and arranger on Alejandro Sanz’s nominated album «Sanz».","type":"text"}]},{"type":"paragraph","content":[{"text":"«Break Out the Crazy»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"With his wife, the singer and dancer Katya Diaz, he forms the New York duo «Break Out the Crazy». They began working together as backup musicians on Alejandro Sanz’s 2012 tour, and their 2024 EP «Vision» includes «Planta», with guitar by the Dominican musician Yasser Tejada.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"As of 2026 he is on tour with Alejandro Sanz, according to his Instagram, and publishes a YouTube channel on music production.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'chris-hierro';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
